```java
@SpringBootTest
@AutoConfigureMockMvc
class WebApiTest {
    @TestConfiguration static class FixedClockConfig {
        @Bean @Primary Clock fixedClock() { return Clock.fixed(Instant.parse("2026-02-01T08:00:00Z"), ZoneOffset.UTC); }
    }
    @Autowired MockMvc mvc;
    @Autowired JdbcTemplate jdbc;
